"""Remaining first DP list: grids, bounded brushes and small row frontiers."""
from nowcoder_editorials import CONTENT, add, read
from nowcoder_two_paths_support import TWO_PATHS


def run():
    existing = read(CONTENT / 'reviewed.json')
    def put(n, *args, **kwargs):
        if f'nowcoder-global::{n}' not in existing:
            add(n, *args, **kwargs)
    put(16615, 1800, ['动态规划', '双路径'], '往返纸条的两条单调路径，内部同学只能帮一次，最大化参与者好感总和。',
        '把返回路径反向，两条路径都从左上到右下，每步向右或向下。同一步的行列和相同，记为step，因此只需状态(step,r1,r2)，列号分别为step−r1、step−r2。每条路上一时刻的行号要么不变（向右），要么少1（向下），共四种转移。\n\n除公共起终点外，不允许两人本步在同一格；而任意一个格只会在固定的行列和时刻出现，所以仅这一检查就排除了整条路径的重复内部点。两路本步增量相加，公共端点只算一次，输入中端点为0。按step滚动存二维表。单行或单列的退化输入不存在可往返的内部中继，按0处理。',
        r'''int rows, cols; cin >> rows >> cols; vector<vector<int>> a(rows,vector<int>(cols)); for (auto &row : a) for (int &x : row) cin >> x; cout << twoPaths(a,true);''',
        '不能先求一条最优路再删点求第二条，两条路径必须联合优化。只允许在起终点重合。', declarations=TWO_PATHS,
        complexity=r'时间 $O((m+n)m^2)$，空间 $O(m^2+mn)$。')
    put(16759, 1700, ['动态规划', '双路径'], '从左上到右下取数两次，允许两路重合，但同一格数字只取一次。',
        '将两次行走同步，状态为(step,r1,r2)，列号由行列和step确定。每人上一状态来自上方或左方，枚举四种前驱，取最大再加当前两格的值。若两人此时在同一格，只加一次。所有可能重合都发生在同一步，因此无需保存访问集合。初态包括左上数字，终态包括右下数字一次。',
        r'''int n; cin >> n; vector<vector<int>> a(n,vector<int>(n)); int r,c,value; while (cin >> r && r != 0) { cin >> c >> value; a[r - 1][c - 1] = value; } cout << twoPaths(a,false);''',
        '本题允许重合，区别于纸条中间人只能帮助一次；重合位置扣掉重复计分即可。输入结束可能是一行0或0 0 0，按第一个0结束读取。', declarations=TWO_PATHS,
        complexity=r'时间 $O(n^3)$，空间 $O(n^2)$。')
    put(16655, 1900, ['动态规划', '坐标压缩'], '青蛙每跳S到T整数距离，终点可越过，最少踩多少石子，桥长可达十亿。',
        '若S=T，落点固定为S的倍数，直接数这些位置的石子。否则S与S+1都允许。任意q≥S(S−1)都能表示成若干个S与S+1之和：取q模S个S+1，余下是非负个S。\n\n用这一性质压缩无石子长间隙。考虑间隙前最近T个位置的DP值，最小值为v。从达到v的那个位置先跳T，便落在间隙中；之后再利用上面的表示式，可以在间隙内走到足够远的任一点。经过至少S(S−1)+2T−1个无石子位置后，最近T个位置均能取得v，也不可能小于v，后面再延长空白就不会改变DP窗口。S<T≤10时这个界至多91，因此相邻事件距离大于100时截成100完全保留窗口信息。\n\n排序石子及终点，将每段距离截到100，做普通DP：f[x]=min(f[x−jump])+此处是否有石子。最终在压缩终点到终点+T−1的落点中取最小，允许跳过桥端。',
        r'''long long length; int s,t,m; cin >> length >> s >> t >> m; vector<long long> stones(m); for (auto &x : stones) cin >> x; sort(stones.begin(),stones.end()); if (s == t) { int answer = 0; for (long long x : stones) answer += x % s == 0; cout << answer; return 0; } long long previous = 0; int compressed = 0; vector<int> marks; for (long long x : stones) { compressed += min<long long>(100,x - previous); marks.push_back(compressed); previous = x; } int target = compressed + min<long long>(100,length - previous), limit = target + t - 1; vector<int> stone(limit + 1), dp(limit + 1,1000000); for (int x : marks) stone[x] = 1; dp[0] = 0; for (int x = 1; x <= limit; x++) { for (int jump = s; jump <= t && jump <= x; jump++) dp[x] = min(dp[x],dp[x - jump] + stone[x]); } cout << *min_element(dp.begin() + target,dp.end());''',
        'S=T时不存在相位混合，不能使用同样的截距压缩。终点不要求恰好落到L，答案需包含越过L的至多T−1个位置。', complexity=r'压缩长度 $L_c\le100(M+1)+T$，时间 $O(M\log M+L_cT)$，空间 $O(L_c)$。')
    put(20471, 1900, ['单调栈', '矩形面积', '网格'], '在01矩阵中分别找最大黑白相间正方形和矩形，输出面积。',
        '把每格颜色异或(行号+列号)的奇偶，原本相邻异色就变为相同色，所以棋盘等价于新矩阵全0或全1子矩形。分别对两种颜色维护以当前行结束的连续同色高度。每一行作为底边，单调栈枚举每个高度能够覆盖的最大宽度width，矩形面积为height*width，可容纳的最大正方形边长为min(height,width)。对所有行、两种颜色取最大。输入逐行处理，只需两组高度。',
        r'''int rows, cols; cin >> rows >> cols; vector<vector<int>> height(2,vector<int>(cols + 1)); long long bestSquare = 0, bestRectangle = 0; for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { int color; cin >> color; color ^= (r + c) & 1; for (int value = 0; value < 2; value++) height[value][c] = color == value ? height[value][c] + 1 : 0; } for (int value = 0; value < 2; value++) { vector<int> stack; for (int c = 0; c <= cols; c++) { while (!stack.empty() && height[value][stack.back()] > height[value][c]) { int h = height[value][stack.back()]; stack.pop_back(); int width = c - (stack.empty() ? -1 : stack.back()) - 1; bestRectangle = max(bestRectangle,1LL * h * width); long long side = min(h,width); bestSquare = max(bestSquare,side * side); } stack.push_back(c); } } } cout << bestSquare << '\n' << bestRectangle;''',
        '必须同时考虑全0和全1两种变换后颜色。正方形要输出面积，不能输出边长。高度数组末尾额外的0用作冲刷栈。', complexity=r'时间 $O(NM)$，额外空间 $O(M)$。')
    put(20242, 2000, ['动态规划', '状态建模', '矩阵'], '只有一列或两列，选恰好k个互不重叠子矩形，最大化总分，格值可为负。',
        '按行扫描，一个矩形跨越多行时，其占据的列集合必须不变。两列时当前行只有五种覆盖形态：空、仅左、仅右、左右两个独立矩形、横跨两列的一个矩形。记录“已启动矩形数、当前形态”的最优分数。\n\n从上一行转移时，当前每个矩形可继续上一行列集合完全相同的矩形，也可重新启动；没有相同列集合则必须启动。枚举可继续者的子集，新增数等于当前矩形数减去继续数，再加本行被覆盖格的分数。允许相邻两行同一列重新启动，因为两个上下接触的矩形仍互不重叠。单列仅保留空与仅左两种形态。最后取启动数恰为k的最大值。',
        r'''int n, m, k; cin >> n >> m >> k; vector<array<int,2>> a(n); for (int r = 0; r < n; r++) for (int c = 0; c < m; c++) cin >> a[r][c]; vector<vector<int>> pattern{{},{1},{2},{1,2},{3}}; int states = m == 1 ? 2 : 5; const long long neg = -(1LL << 60); vector<vector<long long>> dp(k + 1,vector<long long>(states,neg)); dp[0][0] = 0; for (int r = 0; r < n; r++) { vector<vector<long long>> next(k + 1,vector<long long>(states,neg)); for (int previous = 0; previous < states; previous++) for (int current = 0; current < states; current++) { int rectangles = pattern[current].size(), covered = 0, allowed = 0; for (int j = 0; j < rectangles; j++) { int columns = pattern[current][j]; covered |= columns; if (find(pattern[previous].begin(),pattern[previous].end(),columns) != pattern[previous].end()) allowed |= 1 << j; } long long gain = (covered & 1 ? a[r][0] : 0) + (covered & 2 ? a[r][1] : 0); for (int continuation = allowed;; continuation = (continuation - 1) & allowed) { int starts = rectangles - __builtin_popcount((unsigned)continuation); for (int count = 0; count + starts <= k; count++) if (dp[count][previous] != neg) next[count + starts][current] = max(next[count + starts][current],dp[count][previous] + gain); if (continuation == 0) break; } } dp.swap(next); } cout << *max_element(dp[k].begin(),dp[k].end());''',
        '两列同被覆盖时，必须区分一个宽矩形与两个窄矩形，否则会错误计算启动次数。负数情况下仍要求恰好k个，不能初始化全部状态为0。', complexity=r'形态数至多5、继续子集至多4，时间 $O(nk)$，空间 $O(k+n)$，常数由固定五形态决定。')
    put(16496, 2000, ['动态规划', '完全背包', '01背包'], '点击可反复上升、无点击则下降，管道只准严格穿缝，求最少点击或失败前过管数。',
        'dp[h]为到当前横坐标、位于高度h的最少点击数，最左边任意合法高度初值0。进入下一列先处理至少一次点击：由旧dp[h]点击一次，到min(m,h+X)，再按高度递增从本列已上升状态继续点击，类似完全背包。必须先算完上升，再用旧dp的高度h下降Y补入零点击转移，不能从下降后的本列状态继续上升。\n\n随后按该列管道筛掉h≤L或h≥H的状态。若全部不可达，输出0和之前已经通过的管道数；否则若本列有管道，过管数加一。全部列处理完后，输出1及各高度最小值。高度封顶m，反复点击不会高于m。',
        r'''int n,m,k; cin >> n >> m >> k; vector<int> up(n), down(n), low(n + 1,0), high(n + 1,m + 1); vector<bool> pipe(n + 1); for (int i = 0; i < n; i++) cin >> up[i] >> down[i]; while (k--) { int p,l,h; cin >> p >> l >> h; low[p] = l; high[p] = h; pipe[p] = true; } const int inf = 1000000000; vector<int> dp(m + 1,0); dp[0] = inf; int passed = 0; for (int x = 0; x < n; x++) { vector<int> next(m + 1,inf); for (int h = 1; h <= m; h++) { int destination = min(m,h + up[x]); if (dp[h] != inf) next[destination] = min(next[destination],dp[h] + 1); if (next[h] != inf) next[destination] = min(next[destination],next[h] + 1); } for (int h = down[x] + 1; h <= m; h++) next[h - down[x]] = min(next[h - down[x]],dp[h]); for (int h = 1; h <= m; h++) if (h <= low[x + 1] || h >= high[x + 1]) next[h] = inf; if (*min_element(next.begin() + 1,next.end()) == inf) { cout << "0\n" << passed; return 0; } if (pipe[x + 1]) passed++; dp.swap(next); } cout << "1\n" << *min_element(dp.begin() + 1,dp.end());''',
        '缝隙上下边缘均不能碰，必须严格大于L且严格小于H。失败列的管道不能计入已通过数。点击与不点击是互斥的本秒选择。', complexity=r'时间 $O(nm+k)$，空间 $O(n+m)$。')
    put(16696, 1700, ['区间计数', '动态规划', '字符串'], '把字符串分k个非空段，每段可数重叠单词，但同一起点最多选一个词，最大化总词数。',
        '对每个起点i，只需记录能匹配的最短字典词的结束位置end[i]：同起点最多计一个，更短词在任何包含较长词的区间中也完整存在。于是区间[l,r]的最多词数，是其中满足end[i]≤r的起点个数。预处理cost[l][r]=cost[l+1][r]+(end[l]≤r)。\n\n再做分段DP，dp[t][i]表示前i个字符分成t段的最大词数，枚举末段起点j，转自dp[t−1][j]+cost[j][i−1]。只允许j<i，保证每段非空；不可达状态为负无穷。字典词可重叠，但不能跨分段边界。',
        r'''int lines, parts; while (cin >> lines >> parts) { string s, fragment; for (int i = 0; i < lines; i++) { cin >> fragment; s += fragment; } int count; cin >> count; vector<string> words(count); for (auto &w : words) cin >> w; int n = s.size(); vector<int> end(n,n); for (int i = 0; i < n; i++) for (const auto &w : words) if (i + (int)w.size() <= n && s.compare(i,w.size(),w) == 0) end[i] = min(end[i],i + (int)w.size() - 1); vector<vector<int>> cost(n + 1,vector<int>(n)); for (int l = n - 1; l >= 0; l--) for (int r = l; r < n; r++) cost[l][r] = cost[l + 1][r] + (end[l] <= r); const int neg = -1000000000; vector<int> dp(n + 1,neg); dp[0] = 0; for (int p = 1; p <= parts; p++) { vector<int> next(n + 1,neg); for (int i = p; i <= n; i++) for (int j = p - 1; j < i; j++) if (dp[j] != neg) next[i] = max(next[i],dp[j] + cost[j][i - 1]); dp.swap(next); } cout << dp[n] << '\n'; }''',
        '同起点匹配多个词仍只能算一次，不同起点可以重叠。各行输入先拼接，换行不是分段点。', complexity=r'字符串长 $n\le200$、词数 $D\le6$、最长词 $L$，时间 $O(nDL+kn^2)$，空间 $O(n^2)$。')
    put(16129, 2000, ['区间动态规划', '分段动态规划'], '一次只能刷长度至多k的连续段，可覆盖，求得到目标颜色的最少次数。',
        '先求每个长度不超过k的区间的普通“覆盖涂色”最优次数paint[l][r]：可单独刷l后处理其余；也可把l与后面同色位置p放在同一笔中，代价paint[l+1][p−1]+paint[p][r]。因为整个区间长度≤k，其中任何一笔都不会超长。\n\n为什么还可把整面墙分段？两笔若交叉为[a,c]、[b,d]且a<b≤c<d，较早那笔在重叠处已经被较晚那笔覆盖，可删掉这一端的无效部分，笔画长度只会缩短。不断消除交叉后，各笔区间呈包含或互不相交；最外层笔画将整墙划成互不相交的若干段，每段长度都≤k。段内用paint最优地刷，便不会比原方案更差。于是前缀DP best[i]=min(best[l]+paint[l][i−1])，枚举i−l≤k。反之任一这样的分段刷法也合法，故两边等价。',
        r'''int n,k; while (cin >> n >> k) { vector<int> color(n); for (int &x : color) cin >> x; k = min(k,n); vector<vector<int>> paint(n,vector<int>(n)); for (int l = n - 1; l >= 0; l--) { paint[l][l] = 1; for (int r = l + 1; r < n && r - l + 1 <= k; r++) { paint[l][r] = 1 + paint[l + 1][r]; for (int p = l + 1; p <= r; p++) if (color[p] == color[l]) paint[l][r] = min(paint[l][r],(p == l + 1 ? 0 : paint[l + 1][p - 1]) + paint[p][r]); } } vector<int> best(n + 1,n + 1); best[0] = 0; for (int i = 1; i <= n; i++) for (int l = max(0,i - k); l < i; l++) best[i] = min(best[i],best[l] + paint[l][i - 1]); cout << best[n] << '\n'; }''',
        '不能直接把无限长刷子的区间转移加一个“同色点距离≤k”条件，因为被合并的那笔还可能向右延伸，导致总跨度超长。先分成长度合法的最外层段再求段内覆盖。', complexity=r'时间 $O(nk^2)$，空间 $O(n^2)$。')
    put(20273, 1800, ['动态规划', '分组背包'], '每次只能刷一条木板的一段，每格最多刷一次，总次数至多T，最大化正确颜色格数。',
        '先独立处理一条板。j次笔画可分成j个不相交段，每段涂成其中目标颜色的多数色，得分为两种颜色计数的最大值。允许不刷的间隙可延长相邻笔画覆盖，不会减少已正确格数，所以j≥1时可直接枚举把整板分成j个非空段。前缀计数求段得分，做分段DP得到gain[j]；gain[0]=0表示整板不刷。\n\n再将每条木板当一组，枚举给这条板0到M次，做以总笔画次数为容量的分组背包。容量表示至多次数，故初始各容量0，最后取T处最优值。',
        r'''int n,m,budget; cin >> n >> m >> budget; budget = min(budget,n * m); vector<int> total(budget + 1); for (int row = 0; row < n; row++) { string s; cin >> s; vector<int> prefix(m + 1); for (int i = 0; i < m; i++) prefix[i + 1] = prefix[i] + (s[i] == '1'); int cap = min(m,budget), neg = -1000000000; vector<int> gain(cap + 1), dp(m + 1,neg); dp[0] = 0; for (int strokes = 1; strokes <= cap; strokes++) { vector<int> next(m + 1,neg); for (int i = strokes; i <= m; i++) for (int p = strokes - 1; p < i; p++) if (dp[p] != neg) { int ones = prefix[i] - prefix[p]; next[i] = max(next[i],dp[p] + max(ones,i - p - ones)); } dp.swap(next); gain[strokes] = dp[m]; } vector<int> next(budget + 1); for (int b = 0; b <= budget; b++) for (int use = 0; use <= cap && use <= b; use++) next[b] = max(next[b],total[b - use] + gain[use]); total.swap(next); } cout << total[budget];''',
        '每格最多刷一次，与可以覆盖的“涂色”题不同。T可能超过格数，额外次数不增加收益，可截到N*M。', complexity=r'时间 $O(NM^3+NTM)$，空间 $O(M+T)$。')


if __name__ == '__main__':
    run()
